<template><div><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-bold">Leads</h1><p class="mt-2 text-[var(--muted)]">{{ data?.total||0 }} contacts capturés.</p></div><a href="/api/admin/leads/export" class="btn-primary">Exporter CSV</a></div><div class="mt-8 overflow-x-auto rounded-2xl border bg-white dark:bg-[#160630]"><table class="w-full min-w-[850px] text-left text-sm"><thead class="border-b bg-violet-600/5 font-mono text-[10px] uppercase tracking-wider"><tr><th class="p-4">Contact</th><th>Entreprise</th><th>Source</th><th>Ressource</th><th>Statut</th><th>Date</th></tr></thead><tbody><tr v-for="lead in data?.items" :key="lead._id" class="border-b last:border-0"><td class="p-4"><strong>{{ lead.firstName }}</strong><br><a :href="`mailto:${lead.email}`" class="text-violet-700">{{ lead.email }}</a><br><small>{{ lead.phone }}</small></td><td>{{ lead.domain }}</td><td>{{ lead.source }}</td><td>{{ lead.resourceSlug||'—' }}</td><td><select :value="lead.status" class="rounded-lg border bg-transparent p-2 text-xs" @change="status(lead._id,($event.target as HTMLSelectElement).value)"><option v-for="s in statuses" :key="s">{{ s }}</option></select></td><td>{{ new Date(lead.createdAt).toLocaleDateString('fr-FR') }}</td></tr></tbody></table></div></div></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin',i18n:{locales:['fr']}});useSeoMeta({title:'Leads',robots:'noindex,nofollow'});const {data,refresh}=await useFetch<any>('/api/admin/leads');const statuses=['new','contacted','qualified','won','lost'];async function status(id:string,value:string){await $fetch(`/api/admin/leads/${id}`,{method:'PATCH',body:{status:value}});await refresh()}</script>
